import React, { useState, useEffect } from 'react';
import axios from 'axios';
import Loader from './Loader';
import '../App.css';

const NewsPage = () => {
  const [news, setNews] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [lastFetched, setLastFetched] = useState(null);

  useEffect(() => {
    fetchNews();
  }, []);

  const fetchNews = async () => {
    setLoading(true);
    setError(null);

    try {
      const res = await axios.get("http://localhost:5000/news", {
        params: {
          limit: 30
        }
      });

      if (res.data && res.data.news && Array.isArray(res.data.news)) {
        setNews(res.data.news);
        setLastFetched(new Date());
      } else {
        setError('Invalid data format received from server');
      }
    } catch (err) {
      console.error('Error details:', err);
      
      if (err.response) {
        setError(`Server error: ${err.response.data?.error || 'Unknown error'}`);
      } else if (err.request) {
        setError('Server not responding. Please check if backend is running.');
      } else {
        setError(`Failed to fetch news: ${err.message}`);
      }
    } finally {
      setLoading(false);
    }
  };

  function getRelativeTime(date) {
    if (!date) return '';

    const seconds = Math.floor((new Date() - date) / 1000);

    let interval = Math.floor(seconds / 31536000);
    if (interval > 1) return `${interval} years ago`;
    if (interval === 1) return '1 year ago';

    interval = Math.floor(seconds / 2592000);
    if (interval > 1) return `${interval} months ago`;
    if (interval === 1) return '1 month ago';

    interval = Math.floor(seconds / 86400);
    if (interval > 1) return `${interval} days ago`;
    if (interval === 1) return '1 day ago';

    interval = Math.floor(seconds / 3600);
    if (interval > 1) return `${interval} hours ago`;
    if (interval === 1) return '1 hour ago';

    interval = Math.floor(seconds / 60);
    if (interval > 1) return `${interval} minutes ago`;
    if (interval === 1) return '1 minute ago';

    return seconds < 5 ? 'just now' : `${seconds} seconds ago`;
  }

  function formatDateTime(dateString) {
    if (!dateString) return '-';

    const date = new Date(dateString);
    if (isNaN(date.getTime())) return dateString; // Return original if invalid date

    // Format: DD-MM-YYYY HH:MM:SS
    return date.toLocaleString('id-ID', {
      day: '2-digit',
      month: '2-digit',
      year: 'numeric',
      hour: '2-digit',
      minute: '2-digit',
      hour12: false
    });
  }

  // Function to get ticker display name
  function getTickerDisplayName(ticker) {
    const tickerMap = {
      '^GSPC': 'S&P 500',
      '^DJI': 'Dow Jones',
      '^IXIC': 'NASDAQ',
      '^FTSE': 'FTSE 100',
      '^N225': 'Nikkei 225',
      'EURUSD=X': 'EUR/USD',
      'GC=F': 'Gold',
      'CL=F': 'Crude Oil',
      '^JKSE': 'IDX Composite'
    };
    
    return tickerMap[ticker] || ticker;
  }

  return (
    <div className="news-page">
      <section className="hero-section">
        <div className="hero-content">
          <h1>Global Economic News</h1>
          <p>Stay updated with the latest financial and economic news from around the world</p>
          <div className="hero-buttons">
            <button className="btn btn-primary" onClick={fetchNews} disabled={loading}>
              {loading ? 'Refreshing...' : 'Refresh News'}
            </button>
          </div>
          {lastFetched && (
            <div className="last-updated">
              Last updated: {getRelativeTime(lastFetched)}
            </div>
          )}
        </div>
        <div className="hero-image">
          <svg xmlns="http://www.w3.org/2000/svg" width="300" height="300" fill="currentColor" viewBox="0 0 16 16">
            <path d="M0 2.5A1.5 1.5 0 0 1 1.5 1h11A1.5 1.5 0 0 1 14 2.5v10.528c0 .3-.05.654-.238.972h.738a.5.5 0 0 0 .5-.5v-9a.5.5 0 0 1 1 0v9a1.5 1.5 0 0 1-1.5 1.5H1.497A1.497 1.497 0 0 1 0 13.5v-11zM12 14c.37 0 .654-.211.853-.441.092-.106.147-.279.147-.531V2.5a.5.5 0 0 0-.5-.5h-11a.5.5 0 0 0-.5.5v11c0 .278.223.5.497.5H12z"/>
            <path d="M2 3h10v2H2V3zm0 3h4v3H2V6zm0 4h4v1H2v-1zm0 2h4v1H2v-1zm5-6h2v1H7V6zm3 0h2v1h-2V6zM7 8h2v1H7V8zm3 0h2v1h-2V8zm-3 2h2v1H7v-1zm3 0h2v1h-2v-1zm-3 2h2v1H7v-1zm3 0h2v1h-2v-1z"/>
          </svg>
        </div>
      </section>

      {loading && (
        <div className="loading-overlay">
          <Loader />
        </div>
      )}

      {error && <div className="error-message">{error}</div>}

      <section className="news-section">
        <div className="news-grid">
          {news.map((item, index) => (
            <div className="news-card" key={index}>
              <div className="news-card-content">
                <div className="news-meta">
                  <span className="news-source">{item.publisher}</span>
                  <span className="news-date">{formatDateTime(item.publishDate)}</span>
                  {item.ticker && (
                    <span className="news-ticker">{getTickerDisplayName(item.ticker)}</span>
                  )}
                </div>
                <h3 className="news-title">
                  <a href={item.link} target="_blank" rel="noopener noreferrer">
                    {item.title}
                  </a>
                </h3>
                <div className="news-footer">
                  <a href={item.link} target="_blank" rel="noopener noreferrer" className="read-more">
                    Read More
                  </a>
                </div>
              </div>
              {item.thumbnail && (
                <div className="news-thumbnail">
                  <img src={item.thumbnail} alt={item.title} />
                </div>
              )}
            </div>
          ))}
        </div>
      </section>

      {news.length === 0 && !loading && !error && (
        <div className="no-news">
          <p>No news available at the moment. Please try again later.</p>
        </div>
      )}
    </div>
  );
};

export default NewsPage;
